import os
import logging
from flask import Flask, request, Response
from lxml import etree
import boto3
import requests

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# ECS task role credentials are automatically available
sts_client = boto3.client('sts')
s3_client = boto3.client('s3')

DATA_BUCKET = os.environ.get('DATA_BUCKET', 'internal-reports-bucket')
METADATA_URL = 'http://169.254.170.2'  # ECS task metadata endpoint

def get_task_credentials():
    """Retrieve ECS task role credentials from metadata endpoint"""
    try:
        cred_uri = os.environ.get('AWS_CONTAINER_CREDENTIALS_RELATIVE_URI', '')
        if cred_uri:
            resp = requests.get(f"{METADATA_URL}{cred_uri}", timeout=2)
            return resp.json()
    except Exception as e:
        logger.warning(f"Could not fetch task credentials: {e}")
    return None

def validate_content_type(content_type):
    """Basic content type validation"""
    allowed = ['application/xml', 'text/xml', 'application/soap+xml']
    if content_type and any(ct in content_type.lower() for ct in allowed):
        return True
    return False

@app.route('/api/v2/parse-report', methods=['POST'])
def parse_report():
    """Parse XML report and extract summary fields for dashboard"""
    content_type = request.content_type
    if not validate_content_type(content_type):
        return Response('{"error": "Invalid content type"}', status=415)

    xml_data = request.data
    if not xml_data or len(xml_data) > 10 * 1024 * 1024:  # 10MB limit
        return Response('{"error": "Invalid payload size"}', status=400)

    try:
        # Parse XML - note: resolve_entities is True by default in lxml
        parser = etree.XMLParser(
            resolve_entities=True,
            no_network=False,
            load_dtd=True,
            dtd_validation=False
        )
        tree = etree.fromstring(xml_data, parser=parser)

        # Extract report fields
        result = {}
        for field in ['title', 'author', 'date', 'summary', 'department']:
            elem = tree.find(f'.//{field}')
            if elem is not None and elem.text:
                result[field] = elem.text.strip()

        # Store parsed result
        report_id = tree.get('id', 'unknown')
        if result:
            try:
                s3_client.put_object(
                    Bucket=DATA_BUCKET,
                    Key=f'parsed/{report_id}.json',
                    Body=str(result).encode()
                )
            except Exception as e:
                logger.error(f"S3 upload failed: {e}")

        return Response(
            str(result),
            status=200,
            content_type='application/json'
        )
    except etree.XMLSyntaxError as e:
        logger.warning(f"XML parse error: {e}")
        return Response(f'{{"error": "XML parse error"}}', status=400)
    except Exception as e:
        logger.error(f"Unexpected error: {e}")
        return Response('{"error": "Internal error"}', status=500)

@app.route('/api/v2/health', methods=['GET'])
def health():
    """Health check endpoint for ALB target group"""
    creds = get_task_credentials()
    has_creds = creds is not None
    return Response(f'{{"status": "healthy", "has_role": {str(has_creds).lower()}}}', status=200)

@app.route('/api/v2/upload-raw', methods=['POST'])
def upload_raw():
    """Upload raw report to S3 for archival"""
    data = request.data
    filename = request.headers.get('X-Report-Filename', 'unnamed.xml')
    # Sanitize filename
    filename = filename.replace('/', '_').replace('\\', '_')
    try:
        s3_client.put_object(
            Bucket=DATA_BUCKET,
            Key=f'raw/{filename}',
            Body=data
        )
        return Response('{"status": "uploaded"}', status=200)
    except Exception as e:
        logger.error(f"Upload failed: {e}")
        return Response('{"error": "Upload failed"}', status=500)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
